import sys

def is_valid_output(output_lines, n, k):
    pairs = set()
    for b_i, g_i in output_lines:
        if (b_i, g_i) in pairs or (g_i, b_i) in pairs:
            return False
        pairs.add((b_i, g_i))
        if b_i == g_i:
            return False
    for i in range(n - 1):
        if output_lines[i][0] == output_lines[i + 1][0] or output_lines[i][1] == output_lines[i + 1][1]:
            return False
    return True

def solve(n, k):
    if n % 2 == 1:
        return "NO"
    colors = list(range(1, k + 1))
    for i in range(n):
        b_i = colors[i % k]
        g_i = colors[(i + 1) % k] if i % 2 == 0 else colors[(k - (i % k) - 1) % k]
        print(b_i, g_i)
    return "YES"

